'Enable_Pos_Salesperson_Switch_Hint' => 'Afișează un selector de vânzător pe ecranul POS, astfel încât o vânzare să poată fi atribuită altui angajat fără deconectare. Vânzătorul selectat este salvat pe factură și folosit în rapoartele de vânzări; sesiunea POS activă rămâne neschimbată.',
'Wallet_Payment_Method_Missing' => 'Lipsește metoda de plată Portofel',
'Wallet_Payment_Method_Missing_Help' => 'Nu a fost găsită nicio metodă de plată numită exact „Wallet”. Plata cu portofelul din POS este identificată după acest nume, așa că clienții nu pot plăti cu portofelul până nu adăugați aici o metodă de plată numită „Wallet”:',
'Show_Previous_Dues_Line' => 'Afișează linia Datorii anterioare',
'Show_Previous_Dues_Line_Desc' => 'Soldul datorat de client înainte de această vânzare. Tipărit doar când este mai mare decât zero.',
'Show_Net_Balance_Line' => 'Afișează linia Sold net',
'Show_Net_Balance_Line_Desc' => 'Datoriile anterioare plus ce mai este datorat pentru această vânzare. Tipărit doar când datoriile anterioare sunt mai mari decât zero.',
'QZ_Tray_Printer' => 'QZ Tray (imprimantă pe acest calculator)',
'QZ_Printer_Name_Hint' => 'Numele imprimantei așa cum apare pe calculatorul care rulează QZ Tray. Lăsați gol pentru a folosi imprimanta implicită a acelui calculator. Faceți clic pe ⟳ pentru a detecta imprimantele.',
'QZ_Not_Running' => 'QZ Tray nu rulează pe acest calculator. Instalați-l de pe qz.io și lăsați-l să ruleze, apoi permiteți acest site când QZ cere acest lucru.',
'Detect_Printers' => 'Detectează imprimantele',
'QZ_Download_Cert' => 'Descarcă certificatul (override.crt)',
'QZ_Setup_Title' => 'Cum se configurează tipărirea prin QZ Tray (o singură dată, pe fiecare calculator care tipărește etichete)',
'QZ_Step_Install' => '1. Instalați QZ Tray pe acest calculator — descărcați-l gratuit de pe qz.io, apoi porniți-l și lăsați-l să ruleze (se află în zona de notificare pe Windows sau în bara de meniu pe macOS).',
'QZ_Step_Connect' => '2. Conectați imprimanta de etichete prin USB și verificați că este instalată în sistemul de operare (Windows: Setări > Imprimante și scanere — macOS: Setări sistem > Imprimante și scanere).',
'QZ_Step_Detect' => '3. Faceți clic pe butonul ⟳ de lângă „Nume imprimantă” de mai sus pentru a detecta imprimantele de pe acest calculator, apoi selectați imprimanta de etichete. Lăsați câmpul gol pentru a folosi imprimanta implicită a calculatorului.',
'QZ_Step_Cert' => '4. Pentru tipărire fără fereastra de permisiune, descărcați certificatul de mai jos și copiați-l în folderul de instalare QZ Tray, redenumit override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Apoi închideți QZ Tray și porniți-l din nou.',
'QZ_Step_Test' => '5. Faceți clic pe „Tipărește etichetă de test” mai jos. Dacă QZ Tray cere permisiunea, faceți clic pe Allow — cu certificatul instalat nu va mai cere.',
'QZ_Step_Save' => '6. Faceți clic pe Trimite pentru a salva aceste setări. Etichetele din pagina Tipărire coduri de bare se vor tipări acum direct pe această imprimantă, fără fereastra de tipărire a browserului.',
'QZ_Setup_Note' => 'QZ Tray rulează pe calculatorul de pe care navigați, așa că funcționează chiar și când Stocky este găzduit pe un server la distanță. Fiecare calculator care tipărește etichete trebuie să aibă QZ Tray instalat.',
'PWA_Enabled' => 'Activează aplicația instalabilă',
'PWA_Enabled_Help' => 'Permite browserelor să ofere instalarea acestei aplicații pe telefoane, tablete și desktopuri și păstrează în cache paginile care funcționează offline. Dezactivarea elimină peste tot invitația de instalare și golește cache-ul la următoarea vizită.',
