'Label_Render_Mode' => 'Randare etichetă',
'Label_Render_Mode_Hint' => 'Modul în care este desenată eticheta. Fonturile imprimantei sunt cele mai rapide și oferă cel mai clar cod de bare, dar tipăresc doar caractere latine de bază în fontul propriu al imprimantei. Imaginea de previzualizare reproduce exact designul etichetei — fontul ales, orice limbă — așa cum face un software dedicat pentru etichete.',
'Render_Native' => 'Fonturile imprimantei (cel mai rapid)',
'Render_Raster' => 'Imagine de previzualizare (design exact)',
'Label_Width_Mm' => 'Lățime etichetă (mm)',
'Label_Height_Mm' => 'Înălțime etichetă (mm)',
'Label_Size_Hint' => 'Dimensiunea fizică a unui autocolant de pe rolă. Trebuie să corespundă exact etichetelor încărcate — o dimensiune greșită face imprimanta să caute spațiul dintre etichete în locul greșit, astfel încât fiecare etichetă se tipărește tot mai decalat.',
'Calibrate_Labels' => 'Calibrează etichetele',
'Calibrate_Labels_Hint' => 'Imprimanta avansează câteva etichete pentru a măsura autocolantul și spațiul dintre etichete. Rulați o dată după încărcarea unei role noi sau când pozițiile de tipărire se decalează.',
'Calibration_Sent' => 'Calibrarea a început — imprimanta va avansa câteva etichete goale pentru a le măsura. Când se oprește, faceți o tipărire de test.',
'Label_Printer_Dpi' => 'Rezoluție cap de tipărire',
'Label_Printer_Dpi_Hint' => 'Majoritatea imprimantelor de etichete au 203 dpi. Nu sunteți sigur? Folosiți butonul „Află rezoluția” de mai jos — tipărește răspunsul.',
'Find_Resolution' => 'Află rezoluția',
'Find_Resolution_Hint' => 'Tipărește două etichete, marcate 203 și 300. Cea corectă afișează un dreptunghi complet pe autocolant, cu o margine mică și egală pe toate cele patru laturi; cea greșită are margini lipsă sau trece pe autocolantul următor.',
'Dpi_Test_Sent' => 'Se tipăresc două etichete, marcate 203 și 300. Cea corectă afișează un dreptunghi complet, cu o margine mică și egală pe toate cele patru laturi — setați „Rezoluție cap de tipărire” la acel număr și salvați.',
'Label_Offset_X' => 'Decalaj orizontal (mm)',
'Label_Offset_X_Hint' => 'Mută tipărirea lateral pe autocolant. Folosiți când textul este tăiat pe o margine laterală — ex. 2.5 când autocolantul alb este centrat pe o hârtie suport mai lată. Ajustați în pași de 0.5.',
'Label_Offset_Y' => 'Decalaj vertical (mm)',
'Label_Offset_Y_Hint' => 'Mută tipărirea de-a lungul etichetei. Măriți când partea de sus a designului este tăiată sau lipsește; micșorați când începe prea jos.',
'Feed_To_Tear' => 'Avans până la marginea de rupere',
'Feed_To_Tear_Hint' => 'Avansează eticheta până la bara de rupere după fiecare lucrare. Lăsați DEZACTIVAT dacă etichetele se tipăresc decalate în jos sau împărțite între autocolante — multe imprimante nu revin înapoi înainte de eticheta următoare.',
