'Ord_Guide_Intro' => 'Cum ajunge o comandă plasată în magazinul online în stocul și conturile dumneavoastră și unde sunt înregistrați efectiv banii.',
'Ord_Guide_Lifecycle_Title' => 'Stare comandă',
'Ord_Guide_Lifecycle_Pending' => 'O comandă nouă care așteaptă verificarea dumneavoastră. Doar o comandă în așteptare poate fi confirmată sau anulată.',
'Ord_Guide_Lifecycle_Confirmed' => 'Ați acceptat comanda. Stocky creează o vânzare în depozitul ales și scade stocul — acea vânzare este înregistrarea din care citesc rapoartele de stoc, plăți și profit.',
