'Ord_Guide_PaymentStatus_Tip' => 'Setat la finalizarea comenzii și needitabil aici. Faceți clic pentru a vedea cum se înregistrează plata.',
'Ord_Guide_Payment_Title' => 'Stare plată',
'Ord_Guide_Payment_Intro' => 'Această coloană înregistrează modul de plată ales de client la finalizarea comenzii. Este setată de magazin și nu poate fi editată din această pagină — banii propriu-ziși sunt urmăriți pe vânzarea creată la confirmarea comenzii.',
'Ord_Guide_Payment_Paid' => 'Clientul a plătit deja online printr-un procesator de plăți. Confirmarea comenzii creează vânzarea ca Plătită și înregistrează plata pentru dumneavoastră — nu mai trebuie făcut nimic.',
'Ord_Guide_Payment_Pending' => 'Plată la livrare, transfer bancar sau altă metodă de plată ulterioară. Confirmarea comenzii creează vânzarea ca Neplătită, așa că înregistrați singur banii după ce îi încasați — vedeți pașii de mai jos.',
'Ord_Guide_Payment_Failed' => 'Procesatorul a refuzat plata sau clientul a abandonat-o. Comanda este anulată automat.',
'Ord_Guide_MarkPaid_Title' => 'Schimbarea unei plăți din în așteptare în plătită',
'Ord_Guide_MarkPaid_Step1' => 'Confirmați mai întâi comanda aici — confirmarea este cea care creează vânzarea.',
'Ord_Guide_MarkPaid_Step2' => 'Deschideți Vânzări > Toate vânzările și găsiți acea vânzare (același client, iar pagina de detalii arată comanda online din care provine).',
'Ord_Guide_MarkPaid_Step3' => 'Deschideți meniul de acțiuni al rândului și alegeți Creează plată.',
'Ord_Guide_MarkPaid_Step4' => 'Introduceți suma, metoda de plată și data, apoi salvați. Vânzarea trece singură în Parțial sau Plătit, în funcție de sumă.',
'Ord_Guide_MarkPaid_Note' => 'Starea plății afișată aici continuă să înregistreze opțiunea aleasă la finalizarea comenzii și rămâne neschimbată. Vânzarea este înregistrarea contabilă și ea alimentează rapoartele de plăți și profit. Folosiți Afișează plățile pe vânzare pentru a verifica sau edita ce ați introdus.',
'Ord_Guide_Notes_Title' => 'Bine de știut',
'Ord_Guide_Note_Warehouse' => 'Depozitul ales la confirmare decide de unde este luat stocul. Depozitele care nu pot acoperi întreaga comandă sunt marcate cu Stoc epuizat în acea listă.',
'Ord_Guide_Note_Preorder' => 'Articolele precomandate sar peste verificarea stocului, deci o comandă care le conține poate fi confirmată chiar dacă cantitatea nu este încă disponibilă.',
'Ord_Guide_Note_Flagged' => 'O etichetă Semnalat înseamnă că, la finalizare, comanda a declanșat o verificare antifraudă. Treceți cu mouse-ul peste etichetă pentru a vedea motivul și verificați comanda înainte de a o confirma.',
