'VG_Intro' => 'Un produs variabil se vinde sub forma mai multor variante. Construiți-le din opțiuni (recomandat) sau ca o listă simplă de nume. Fiecare variantă are propriul cod, prețuri, imagine și stoc.',
'VG_Options_Title' => 'Mod opțiuni (culoare, mărime...)',
'VG_Opt_Step1' => 'Lăsați comutatorul din antetul cardului pe „Opțiuni”.',
'VG_Opt_Step2' => 'Tastați un nume de opțiune, precum Culoare sau Mărime, sau alegeți una dintre sugestii.',
'VG_Opt_Step3' => 'Tastați o valoare (de exemplu Roșu) și apăsați Enter. Repetați pentru fiecare valoare; și virgula separă valorile. Faceți clic pe x de pe o valoare pentru a o elimina.',
'VG_Opt_Step4' => 'Faceți clic pe „Adaugă opțiune” pentru a doua sau a treia opțiune (maximum 3 opțiuni).',
