'VG_Opt_Step8' => 'Opțional: bifați „Mostre de culoare” la o opțiune și alegeți o culoare pentru fiecare valoare; magazinul o afișează ca un punct colorat.',
'VG_Rows_Title' => 'Rânduri variante',
'VG_Rows_Text' => 'Fiecare rând are o imagine, cod, cod de bare, cost, preț, preț en-gros și preț minim de vânzare. La crearea unui produs puteți introduce și stocul inițial pe depozit pentru fiecare variantă. O etichetă „Incomplet” înseamnă că rândului îi lipsește o valoare pentru o opțiune.',
'VG_List_Title' => 'Mod listă simplă',
'VG_List_Text' => 'Tastați un nume de variantă și apăsați Enter (sau faceți clic pe Adaugă) pentru a adăuga un rând, apoi completați codul și prețurile. Acesta este comportamentul clasic și rămâne disponibil pentru produsele existente.',
'VG_Edit_Title' => 'Editare ulterioară',
'VG_Edit_1' => 'Adăugați o valoare și faceți clic pe „Generează variante”: se adaugă doar combinațiile lipsă. Rândurile existente își păstrează codurile, prețurile și istoricul.',
'VG_Edit_2' => 'Eliminarea unei valori sau a unei opțiuni elimină rândurile care o folosesc. Rândurile deja salvate sunt șterse la salvarea produsului, după o confirmare.',
