'Upd_Guide_Before_Title' => '1. Înainte de actualizare',
'Upd_Guide_Before_Download' => 'Descărcați {package} al aplicației din contul CodeCanyon ({path}). Nu îl extrageți — programul de actualizare are nevoie de ZIP exact așa cum a fost descărcat.',
