'Upd_Guide_Before_No_Manual' => '{not} trebuie să faceți backup manual, să extrageți fișiere, să rulați comenzi, să editați fișiere de configurare sau să umblați la baza de date — programul de actualizare face toate acestea automat. (Un backup manual suplimentar nu strică, desigur.)',
'Upd_Not' => 'Nu',
'Upd_Guide_Code_Overwritten' => 'Dacă ați modificat manual codul aplicației, modificările vor fi suprascrise de actualizare. Datele, fișierele încărcate, setările și .env sunt întotdeauna păstrate.',
