'Upd_Guide_Run_Upload' => '{upload}: faceți clic sau trageți pachetul descărcat în caseta de încărcare. Fișierele mari sunt încărcate în bucăți mici, deci funcționează și pe hosting partajat cu limite mici de încărcare. O sumă de control protejează împotriva încărcărilor corupte sau incomplete.',
'Upd_Upload_The_Zip' => 'Încărcați fișierul ZIP',
'Upd_Guide_Run_Validation' => '{auto} după încărcare (o puteți rula din nou cu butonul {button}). Sistemul verifică: integritatea ZIP, structura și completitudinea pachetului, compatibilitatea versiunii (retrogradările sunt refuzate), versiunea și extensiile PHP necesare, permisiunile fișierelor, spațiul liber pe disc, conexiunea la baza de date, configurarea și că nu rulează altă actualizare.',
'Upd_Validation_Runs_Automatically' => 'Validarea rulează automat',
'Upd_Guide_Run_Review' => 'Examinați panoul {panel}. Butonul {button} apare doar când toate verificările critice trec. Dacă o verificare eșuează, mesajul vă spune exact ce trebuie corectat.',
