'Upd_Keep_Page_Open' => 'păstrați această pagină deschisă',
'Upd_Guide_Phase_Backup' => '{label} — se creează și se {verified} un dump complet al bazei de date, un ZIP cu toate fișierele aplicației pe care actualizarea le poate modifica și o copie a {env}. Fișierele încărcate ({images}) și {storage} nu sunt niciodată atinse de o actualizare, deci nu sunt arhivate. Dacă backup-ul nu poate fi creat, actualizarea se oprește aici și nu se modifică nimic.',
'Upd_Verified' => 'verifică',
'Upd_Guide_Phase_Prepare' => '{label} — noua versiune este extrasă într-o zonă de pregătire și validată din nou. Aplicația live rămâne încă neatinsă.',
'Upd_Guide_Phase_Maintenance' => '{label} — modul mentenanță este activat; vizitatorii văd un ecran prietenos „Revenim imediat”.',
'Upd_Guide_Phase_Files' => '{label} — fișierele noi sunt comutate aproape instantaneu; fișierele vechi sunt păstrate deoparte pentru revenire. Căile protejate ({env}, {storage}, {images}) nu sunt niciodată înlocuite.',
'Upd_Guide_Phase_Database' => '{label} — rulează migrările, apoi sunt reîmprospătate permisiunile, traducerile și șabloanele.',
'Upd_Guide_Phase_Cache' => '{label} — toate cache-urile sunt golite și reconstruite.',
'Upd_Guide_Phase_Verify' => '{label} — verificările de sănătate confirmă că noua versiune pornește, baza de date funcționează, toate migrările au rulat și configurarea este validă.',
'Upd_Guide_Phase_Done' => '{label} — modul mentenanță este dezactivat și fișierele temporare sunt curățate.',
'Upd_Guide_Run_Success' => 'Când vedeți {success}, faceți clic pe {reload} și reîmprospătați complet browserul ({keys}) pentru ca noile resurse ale panoului de administrare să se încarce.',
'Upd_Update_Successful_Short' => 'Actualizare reușită',
'Upd_Guide_No_Internet' => 'Nu este necesară conexiune la internet în timpul actualizării — totul provine din ZIP-ul încărcat. Pierderea conexiunii sau închiderea browserului NU întrerupe actualizarea: serverul reține exact unde s-a oprit.',
'Upd_Guide_Wrong_Title' => '3. Dacă ceva nu merge bine',
'Upd_Guide_Wrong_Rollback' => '{label} — dacă ceva eșuează după ce fișierele au început să se schimbe (eroare de extragere, migrare eșuată, verificare de sănătate eșuată, disc plin, …), sistemul restaurează automat fișierele anterioare și baza de date din backup-ul verificat, dezactivează modul mentenanță și raportează {message}. Ajungeți exact de unde ați plecat.',
'Upd_Automatic_Rollback' => 'Revenire automată',
'Upd_Failed_Previous_Restored' => 'Actualizare eșuată — versiunea anterioară a fost restaurată',
'Upd_Guide_Wrong_Interrupted' => '{label} (repornire server, timeout, browser închis, pană de curent) — când redeschideți această pagină, un banner roșu oferă două opțiuni sigure: {resume} (reia de la pasul exact unde s-a oprit) sau {rollback} (restaurează versiunea anterioară din backup).',
'Upd_Interrupted_Update' => 'Actualizare întreruptă',
'Upd_Guide_Wrong_Unreachable' => '{label} — folosiți {console} independentă de la {path}. Funcționează chiar și când site-ul este în modul mentenanță sau resursele panoului de administrare sunt defecte și oferă aceleași acțiuni Continuă / Revino. Există și un link discret „Acces administrator” în partea de jos a ecranului de mentenanță.',
'Upd_Admin_Unreachable' => 'Panou de administrare inaccesibil',
'Upd_Recovery_Console' => 'consola de recuperare',
'Upd_Guide_Wrong_Locked_Out' => '{label} — cât timp rulează o actualizare, această pagină afișează un {link}. Salvați-l dacă trebuie să reveniți (de exemplu după expirarea sesiunii); vă permite să treceți de ecranul de mentenanță pentru a vă autentifica din nou.',
'Upd_Locked_Out_Maintenance' => 'Blocat de modul mentenanță',
'Upd_Bypass_Link' => 'link de ocolire',
'Upd_Guide_Wrong_Concurrent' => '{label} — va vedea {message} Doar o actualizare poate rula la un moment dat.',
'Upd_Another_Admin_Updating' => 'Alt administrator încearcă să actualizeze în același timp',
'Upd_Guide_Backups_Title' => '4. Backup-uri și restaurare',
'Upd_Guide_Backups_Created' => 'Fiecare actualizare creează un backup {before} de a atinge ceva: toate fișierele aplicației pe care actualizarea le poate înlocui, o copie a {env} și un dump complet al bazei de date. Fișierele încărcate și {storage} nu sunt niciodată modificate de o actualizare și, prin urmare, nu fac parte din backup — păstrați-vă propriile copii ale acestora. Backup-urile se află în {path} și nu sunt niciodată accesibile de pe web.',
'Upd_Before' => 'înainte',
'Upd_Guide_Backups_Panel' => 'Panoul {panel} din fila {tab} le listează cu dată, versiune și dimensiune. De acolo puteți {restore} orice backup complet (fișiere + bază de date — mai întâi se face o copie de siguranță a bazei de date curente) sau {delete} pe cele vechi.',
'Upd_Restore_Verb' => 'restaura',
'Upd_Delete_Verb' => 'șterge',
'Upd_Guide_Backups_Retention' => 'Folosiți {keep} pentru a alege câte backup-uri sunt păstrate; cele mai vechi sunt eliminate automat după fiecare actualizare reușită. Singurul backup complet rămas nu poate fi șters niciodată — păstrați întotdeauna o cale de întoarcere.',
'Upd_Guide_Manual_Title' => '5. Actualizare manuală (metodă de rezervă)',
'Upd_Guide_Manual_Text' => 'Dacă preferați să actualizați manual sau programul de încărcare nu poate fi folosit pe serverul dvs., urmați instrucțiunile pas cu pas din fila {tab} a acestei pagini.',
'Upd_Guide_Clear_Cache_First' => 'Dacă paginile arată defect sau goale după orice actualizare, goliți mai întâi memoria cache a browserului — aproape întotdeauna aceasta este cauza.',
'Upd_Restore_Backup_Confirm' => 'Restaurați acest backup? Fișierele curente și baza de date curentă vor fi înlocuite de backup. Mai întâi se face o copie de siguranță a bazei de date curente. (v{version} — {date})',
'Woo_Guide_Lead' => 'Cum se menține un magazin WooCommerce sincronizat cu ERP-ul. Liniile cron de mai jos sunt generate pentru acest server, deci pot fi copiate direct pe el.',
'Woo_Guide_Ways_Note' => 'Spre deosebire de Shopify, WooCommerce nu trimite nimic către ERP de la sine — aici nu există receptor de webhook, deci tot ce intră {in} sosește conform programului. Doar stocul care iese {out} poate fi imediat.',
'Woo_In' => 'în',
'Woo_Out' => 'spre exterior',
'Woo_Guide_Both_Ways_Title' => 'Ambele direcții au nevoie mai întâi de asta',
'Woo_Api_Keys' => 'Chei API',
'Woo_Guide_Api_Keys_Text' => '{path}, permisiunea {perm}. Copiați cheia și secretul consumatorului în fila {settings}, împreună cu URL-ul magazinului — adresa site-ului fără bară oblică la final, de ex. {example}.',
'Woo_Credentials_Saved' => 'credențiale salvate',
'Woo_Not_Configured_Yet' => 'neconfigurat încă',
'Woo_Guide_Wp_App_Password_Title' => 'Parolă de aplicație WordPress (opțional)',
'Woo_Guide_Wp_App_Password_Text' => 'Folosită doar pentru imaginile produselor. API-ul WooCommerce transferă produse, stoc, categorii, mărci, clienți și comenzi; API-ul WordPress caută în Biblioteca media și încarcă o imagine care nu există încă acolo.',
'Woo_Guide_Wp_App_Password_Note' => 'Folosiți un utilizator WordPress care poate gestiona media și creați parola din {path}. Lăsați ambele câmpuri goale și totul se sincronizează în continuare — doar atașarea imaginilor este omisă.',
'Woo_Guide_Pick_Way_Title' => 'Apoi alegeți cum se menține sincronizat',
'Woo_Right_Away' => 'Imediat',
'Woo_Stock_Live' => 'stoc în timp real',
'Woo_Stock_Not_Live' => 'stoc nu în timp real',
'Woo_Guide_Realtime_Lead' => 'O singură direcție: stocul și produsele care pleacă din ERP. Comenzile și modificările de produse făcute în WooCommerce sosesc tot conform programului — vedeți cealaltă filă.',
'Woo_Push_Stock_On_Change' => 'Trimite stocul în momentul în care se modifică',
'Woo_Setting_People_Miss' => 'Aceasta este setarea pe care oamenii o ratează',
'Woo_Guide_Pos_Sale_Not_Reach' => 'O vânzare POS {not} ajunge singură în WooCommerce. Dacă e dezactivată, magazinul află abia la următoarea sincronizare de stoc — implicit o oră — iar în acest interval poate vinde o unitate pe care ați vândut-o deja la casă.',
'Woo_Does_Not' => 'nu',
'Woo_Guide_Tick_Instant' => 'Bifați {option} în fila {settings}. Aceasta este toată configurarea — fără worker, fără cron. Fiecare vânzare, retur, ajustare, transfer și achiziție recepționată trimite apoi o actualizare doar pentru acele produse, imediat după salvarea vânzării, iar o vânzare cu douăzeci de linii costă o singură trimitere, nu douăzeci. Casa nu așteaptă niciodată după ea.',
'Woo_Currently' => 'În prezent:',
'Woo_Instant_On_Text' => 'activat — stocul este trimis la modificare',
'Woo_Instant_Off_Text' => 'dezactivat — stocul doar conform programului',
'Woo_Guide_Instant_Note' => 'Sunt trimise doar produsele deja asociate cu WooCommerce — unul care nu a fost niciodată sincronizat nu are nimic de corectat în magazin. Produsele variabile trec prin produsul părinte, iar un combo este retrimis când oricare dintre componentele sale se mișcă. Operațiile în masă (ștergerea unui produs, resetarea unui depozit) scriu stocul fără a declanșa un eveniment, acesta fiind un motiv în plus să păstrați și sincronizarea orară a stocului.',
'Woo_Push_Products_On_Save' => 'Trimite produsele în momentul în care sunt salvate',
'Woo_Guide_Tick_Auto_Products' => 'Bifați {option} în fila {settings}, iar un produs creat, editat sau duplicat în Stocky este trimis la WooCommerce imediat după salvare — detalii, preț, variante și imagini, apoi stocul. Un produs nou este creat în magazin imediat, în loc să aștepte sincronizarea nocturnă a produselor.',
'Woo_On' => 'activat',
'Woo_Off' => 'dezactivat',
'Woo_Guide_Bulk_Imports_Note' => 'Importurile în masă nu sunt trimise unul câte unul — rulați o sincronizare de produse după un import. Sincronizați mai întâi categoriile și mărcile, astfel încât un produs trimis să ajungă în categoria corectă.',
'Woo_Nothing_Else_To_Install' => 'Nimic altceva de instalat',
'Woo_Guide_Same_Process' => 'Fără worker de coadă, fără intrare cron. Trimiterea rulează în același proces care a servit vânzarea, {after} ce răspunsul a fost trimis, deci casa nu așteaptă niciodată după WooCommerce. Trimiterile nu se suprapun niciodată: modificările făcute în timp ce una rulează așteaptă și pleacă imediat după.',
'Woo_After' => 'după',
'Woo_Guide_Shop_Stops_Answering' => 'Un magazin care nu mai răspunde este abandonat după opt secunde, iar trimiterile se întrerup timp de cinci minute, astfel încât fiecare vânzare să nu mai aștepte după el; modificările apărute între timp pleacă odată cu prima trimitere de după pauză, iar sincronizarea orară a stocului recuperează oricum. Fiecare pauză este înregistrată în fila Jurnale.',
'Woo_Guide_Artisan_Exception' => 'O excepție: o modificare de stoc făcută de o comandă artisan nu are un răspuns după care să ruleze, deci este pusă în coada {queue}. Pentru ca și acestea să plece rapid, procesați acea coadă:',
'Woo_Cron_Line_Copied' => 'Linie cron copiată',
'Woo_Command_Copied' => 'Comandă copiată',
'Woo_Guide_Not_Woo_Queue' => 'Intenționat nu coada {queue}: aceasta transportă loturile de catalog care durează ore întregi, iar o trimitere instantanee pusă în spatele uneia nu ar mai fi instantanee.',
'Woo_On_A_Schedule' => 'Conform programului',
'Woo_Guide_Scheduled_Lead' => 'Totul este reverificat periodic, în ambele direcții. Așa ajung comenzile în ERP, așa se publică un catalog și așa se repară tot ce a ratat calea rapidă. Fiecare sarcină are propria intrare cron, deci rulați doar ce doriți.',
'Woo_Guide_Sync_Drains_Queue' => '{command} își procesează propria coadă în timp ce rulează, deci aceste linii nu au nevoie de un worker separat. Pe Windows, folosiți Task Scheduler cu programul {program} și aceleași argumente, pornit în {path}.',
'Woo_Or_No_Cron' => 'Sau fără cron deloc',
'Woo_Guide_No_Cron_Text' => 'Fiecare filă de aici sincronizează la cerere, iar o sincronizare manuală își procesează propriile loturi cât timp pagina este deschisă — deci un magazin mic poate funcționa fără nicio intrare cron. Ce pierdeți este tot ce se întâmplă cât nu se uită nimeni: comenzile sosesc doar când cineva apasă butonul.',
'Woo_Commands_Worth_Knowing' => 'Comenzi utile',
'Woo_Worth_Knowing' => 'Bine de știut',
'Woo_Guide_Changing_Url_Clears' => 'Schimbarea URL-ului magazinului sau a cheilor API șterge toate asocierile — produsele, categoriile, mărcile și clienții se sincronizează toate din nou cu noul magazin.',
'Woo_Guide_Keep_Skus' => 'Mențineți SKU-urile consecvente între Stocky și WooCommerce: asta previne duplicatele și face reasocierea sigură.',
'Woo_Guide_Stock_Total' => 'Stocul publicat în Woo este {total}, nu cifra unui singur depozit.',
'Woo_Total_Across_Warehouses' => 'totalul din toate depozitele',
'Woo_Guide_Full_Reference' => 'Referința completă — fiecare domeniu, cum se comportă coada și o listă de depanare — se află în {file}.',
'Woo_Way_Covers' => 'Acoperă',
'Woo_Way_Covers_Realtime' => 'Doar stocul care pleacă din ERP — o vânzare POS, un retur, o ajustare, o achiziție recepționată',
'Woo_Way_Covers_Scheduled' => 'Totul, în ambele direcții: comenzi și modificări de produse spre interior, catalog și stoc spre exterior',
