'Woo_Cron_Orders' => 'Comenzi la fiecare 15 minute — doar cele modificate de la ultima rulare.',
'Woo_Cron_Products_Pull' => 'Modificări de produse din magazin, în fiecare noapte la 03:00.',
'Woo_Cron_Customers' => 'Clienți, în fiecare noapte la 03:30.',
'Woo_Cron_Stock' => 'Stoc la fiecare oră — plasa de siguranță sub trimiterea instantanee și singura sincronizare de stoc fără ea.',
