'Woo_Guide_Page_Title' => 'Ghid WooCommerce',
'Woo_Guide_Page_Subtitle' => 'Conectarea magazinului, ce rulează automat și intrările cron pentru acest server',
'Woo_Settings_Button' => 'Setări WooCommerce',
'Woo_No_Shop_Connected' => 'Încă nu este conectat niciun magazin',
'Woo_No_Shop_Connected_Desc' => 'Tot ce urmează rămâne valabil — introduceți URL-ul magazinului și cheile API în pagina de setări WooCommerce, apoi reveniți.',
'Woo_Wp_Username' => 'Nume utilizator WordPress',
'Woo_Wp_App_Password' => 'Parolă de aplicație WordPress',
'Woo_Settings_Instant_Hint' => 'O vânzare, un retur sau o ajustare trimite o actualizare de stoc doar pentru acele produse în momentul salvării, astfel încât magazinul este corect în câteva secunde, nu la următoarea sincronizare orară a stocului. Nimic altceva de instalat — trimiterea rulează după ce vânzarea a primit răspuns, deci casa nu așteaptă niciodată după WooCommerce. Mai multe în fila {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Dacă rămâne dezactivată, o vânzare POS ajunge în WooCommerce doar la următoarea sincronizare de stoc — până la o oră mai târziu.',
'Woo_Settings_Auto_Products_Hint' => 'Un produs creat, editat sau duplicat în Stocky este trimis la WooCommerce imediat după salvare — detalii, preț, variante, imagini, apoi stocul — în loc să aștepte o sincronizare de produse. Importurile în masă nu sunt trimise; rulați o sincronizare de produse după un import.',
'Woo_Sync_Tuning' => 'Reglarea sincronizării',
'Woo_Sync_Tuning_Intro' => 'Valorile implicite se potrivesc majorității magazinelor. Modificați-le doar dacă sincronizarea este lentă sau expiră pe hostingul dvs. Fiecare valoare este limitată la un interval sigur, iar golirea unui câmp restaurează valoarea implicită.',
'Woo_Setting_This_Up' => 'Configurare',
'Woo_Setting_This_Up_Text' => 'Obținerea cheilor API, la ce folosește parola de aplicație WordPress, intrările cron pentru sincronizările programate și cum să faceți ca stocul să ajungă în magazin în momentul în care se modifică — toate acestea, cu liniile cron ale acestui server gata de copiat, se află în fila Ghid. O singură copie, ca să nu se poată îndepărta de ce face efectiv modulul.',
