'Jumia_Guide_3' => 'Asigurați-vă că {sku} al fiecărei listări Jumia este egal cu codul produsului din Stocky — aceasta este identitatea folosită atât pentru trimiterea stocului, cât și pentru potrivirea comenzilor.',
