'Shopify_G_Lead_Store' => 'De ce are nevoie acest magazin pentru a rămâne sincronizat. Tot ce este aici este specific acestui magazin — căile și ID-urile sunt reale, deci comenzile pot fi copiate direct pe server.',
'Shopify_G_Lead_Generic' => 'Cum se menține un magazin Shopify sincronizat cu ERP-ul. Alegeți un magazin mai sus pentru a-i vedea starea proprie sau citiți-l așa cum este — linia cron și URL-ul webhook sunt aceleași indiferent de magazinul conectat.',
'Shopify_G_Ways_Note' => 'Majoritatea magazinelor le rulează pe amândouă: prima menține magazinul actualizat minut cu minut, a doua prinde tot ce a ratat prima — un webhook care n-a sosit niciodată, o editare făcută direct în administrarea Shopify, o noapte în care site-ul a fost căzut.',
'Shopify_G_Both_Need' => 'Ambele direcții au nevoie mai întâi de asta',
'Shopify_G_Credentials' => 'Credențiale Shopify',
'Shopify_G_Cred_Intro' => 'Din ianuarie 2026 Shopify nu mai creează aplicații personalizate în administrare, deci există două tipuri de conexiune:',
'Shopify_G_Cred_DevDash' => '{app} (orice magazin conectat acum) — {path}. Acordați scope-urile Admin API pentru ce sincronizează acest magazin, instalați aplicația pe magazin, apoi copiați {clientId} și {clientSecret} din pagina Settings a aplicației în {where}. ERP-ul le schimbă singur pe un token de acces și îl reînnoiește înainte să expire, la fiecare 24 de ore. Client secret-ul semnează și webhook-urile, deci nu mai este nevoie de nimic altceva. Aplicația și magazinul trebuie să se afle în aceeași organizație Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'Aplicație Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (creată în administrare înainte de 2026) — continuă să funcționeze neschimbată cu {token} ({prefix}) și cu {secret} ca secret de semnare webhook. Nu este aceeași valoare ca tokenul, iar inversarea lor este motivul obișnuit pentru care webhook-urile sunt refuzate.',
'Shopify_G_Legacy_App' => 'Aplicație personalizată veche',
'Shopify_G_API_Secret_Key' => 'Cheie secretă API',
'Shopify_G_Stored' => 'stocat',
'Shopify_G_Missing_Refused' => 'lipsă — livrările vor fi refuzate',
'Shopify_G_Where_Data_Desc' => '{path} Depozitul ERP al cărui stoc îl vinde acest magazin și locația Shopify în care este scris acel stoc. Sincronizarea inventarului și importul comenzilor refuză să ruleze fără ele.',
'Shopify_G_Currently' => 'În prezent: depozit {warehouse}, locație {location}',
'Shopify_G_Not_Set_Lower' => 'nesetat',
'Shopify_G_Ready' => 'pregătit',
'Shopify_G_Incomplete' => 'incomplet',
'Shopify_G_Manual_Syncs' => 'Sincronizări pornite manual',
'Shopify_G_Manual_Desc' => 'O sincronizare pornită din {centre} răspunde imediat și rulează în fundal, în segmente scurte care continuă fiecare de unde s-a oprit cel anterior. Un catalog mare nu este niciodată întrerupt la jumătate de un hosting care încheie cererile web lungi (LiteSpeed, nginx, un load balancer), iar închiderea paginii nu o oprește. Worker-ul pentru aceasta este încă o linie cron:',
'Shopify_G_Cron_Copied' => 'Linie cron copiată',
'Shopify_G_Manual_Note' => 'Fără ea, o sincronizare se finalizează totuși, dar doar cât timp pagina Centrul de sincronizare rămâne deschisă: când niciun worker nu preia o rulare în câteva secunde, pagina o continuă singură, câte o cerere scurtă. Pe Windows folosiți Task Scheduler la fiecare minut: programul {program}, argumentele {args}, pornit în {dir}.',
'Shopify_G_Then_Pick' => 'Apoi alegeți cum se menține sincronizat',
'Shopify_G_Right_Away' => 'Imediat',
'Shopify_G_Stock_Live' => 'stoc în timp real',
'Shopify_G_Stock_Not_Live' => 'stoc nu în timp real',
'Shopify_G_Realtime_Lead' => 'Fiecare modificare este trimisă pe măsură ce are loc, în câteva secunde. Două jumătăți, cu comutatoare separate: {webhooks} aduc evenimentele magazinului, iar {push} trimite stocul spre exterior.',
'Shopify_G_Webhooks_Lower' => 'webhook-urile',
'Shopify_G_Instant_Push_Lower' => 'trimiterea instantanee a stocului',
'Shopify_G_Webhooks_In' => 'Webhook-uri — magazinul → ERP',
'Shopify_G_Webhooks_Desc' => 'Comenzi, modificări de stare a comenzilor și editări de produse, clienți și stoc făcute în Shopify. Deschideți magazinul și apăsați {button} în {tab} — se poate apăsa de două ori fără probleme. Shopify trimite către:',
'Shopify_G_Webhooks_Tab' => 'fila Webhook-uri',
'Shopify_G_Webhooks_Note' => 'Adresa trebuie să fie accesibilă de pe internet prin HTTPS — Shopify nu livrează către {localhost} sau către un domeniu {test}. Fiecare livrare este înregistrată o singură dată, deci reîncercările Shopify nu pot crea o comandă duplicată, iar una eșuată poate fi reluată. Livrările sunt refuzate până când secretul de semnare de la pasul 1 este stocat.',
'Shopify_G_Instant_Out' => 'Trimiterea instantanee a stocului — ERP → magazinul',
'Shopify_G_Setting_Missed' => 'Aceasta este setarea pe care oamenii o ratează',
'Shopify_G_Pos_Not_Auto' => 'O vânzare POS {not} ajunge singură în Shopify. Dacă e dezactivată, magazinul află abia la următorul pas de trimitere a inventarului — iar în acest interval poate vinde o unitate pe care ați vândut-o deja la casă.',
'Shopify_G_Not' => 'Nu',
'Shopify_G_Tick_Push' => 'Bifați {setting} în {where}. Aceasta este toată configurarea — fără worker, fără cron. Fiecare vânzare, retur și ajustare trimite apoi o actualizare doar pentru acele produse, imediat după salvarea vânzării, iar o vânzare cu douăzeci de linii costă o singură trimitere, nu douăzeci. Casa nu așteaptă niciodată după ea.',
'Shopify_G_This_Store' => 'Acest magazin:',
'Shopify_G_Push_On' => 'activat — stocul este trimis la modificare',
'Shopify_G_Push_Off' => 'dezactivat — stocul doar conform programului',
'Shopify_G_Push_Note' => 'Sunt trimise doar produsele care au deja o asociere Shopify și doar mișcările din depozitul acestui magazin. Operațiile în masă — ștergerea unui produs, resetarea unui depozit — scriu stocul fără a declanșa un eveniment, acesta fiind un motiv în plus să păstrați și pasul programat de inventar.',
'Shopify_G_Nothing_Install' => 'Nimic altceva de instalat',
'Shopify_G_No_Worker_Note' => 'Niciuna dintre jumătăți nu are nevoie de un worker de coadă sau de o intrare cron. Un webhook care intră este tratat în cererea făcută de Shopify; o trimitere de stoc care iese rulează în același proces care a servit vânzarea, {after} ce răspunsul a fost trimis — deci casa nu așteaptă niciodată după Shopify, iar un magazin care nu mai răspunde este abandonat după zece secunde și lăsat pentru următoarea trimitere programată de inventar.',
'Shopify_G_After' => 'după',
'Shopify_G_Artisan_Note' => 'O excepție: o modificare de stoc făcută de o comandă artisan nu are un răspuns după care să ruleze, deci este pusă în coada {queue}. Dacă doriți ca și acestea să plece rapid, procesați acea coadă:',
'Shopify_G_On_Schedule' => 'Conform programului',
'Shopify_G_On_Lower' => 'activat',
'Shopify_G_Off_Lower' => 'dezactivat',
'Shopify_G_Scheduled_Lead' => 'Totul este reverificat periodic, în ambele direcții. Mai lent decât timpul real, dar este ceea ce trimite stocul în magazinele care nu folosesc trimiterea instantanee, ceea ce prinde un webhook ratat și singura cale de a muta un catalog întreg.',
'Shopify_G_Cron_Entry' => 'Intrarea cron',
'Shopify_G_Cron_Entry_Desc' => 'Nimic programat nu rulează fără ea. O singură linie, doar pentru acest modul — adăugați-o lângă orice altceva ați ales să programați:',
'Shopify_G_Cron_Note' => 'La fiecare cinci minute este cea mai fină rezoluție pe care o poate folosi un plan, deoarece cinci minute este cel mai scurt interval de pas. O intrare mai rară devine pur și simplu pragul minim — cu {example}, un pas setat la 5 minute rulează la fiecare 15. Pe Windows folosiți Task Scheduler: programul {program}, argumentele {args}, pornit în {dir}.',
'Shopify_G_Switch_On_Plan' => 'Activați-o și alegeți planul',
'Shopify_G_Plan_Desc' => '{where} Comutatorul decide dacă cron-ul poate acționa; planul decide ce face. Un {step} este o entitate într-o direcție cu propriul interval — {first}, {second}. Intervalul implicit este folosit de orice pas care își lasă propria casetă goală.',
'Shopify_G_Step_Lower' => 'pas',
'Shopify_G_Plan_Note' => 'Lăsați planul gol și magazinul preia comenzile și trimite stocul la intervalul implicit, ceea ce doresc majoritatea magazinelor. Comenzile sunt doar preluate: Shopify este locul unde un client plasează o comandă.',
'Shopify_G_Schedule_On' => 'program activat',
'Shopify_G_Schedule_Off' => 'program dezactivat — doar manual',
'Shopify_G_When_Step_Runs' => 'Când rulează efectiv un pas',
'Shopify_G_When_Note' => 'Un pas este scadent când același pas a {started} ultima dată de mai mult timp decât intervalul său, conform istoricului rulărilor. Astfel, o sincronizare pornită manual o amână pe următoarea automată, iar un pas care eșuează mereu este reîncercat la intervalul său, nu la fiecare tic. Prezentarea generală a magazinului arată ultima rulare a fiecărui pas, următoarea scadență și motivul blocării, dacă este blocat. Rulați manual prima trimitere a catalogului — mai întâi cu {dryRun} — înainte de a o programa.',
'Shopify_G_Started_Lower' => 'pornit',
'Shopify_G_Where_Setting' => 'Unde se află fiecare setare',
'Shopify_G_Where_Setting_Note' => 'Toate acestea se află pe un magazin existent: {path}, apoi creionul (sau {edit} în pagina proprie a magazinului).',
'Shopify_G_Product_Images' => 'Imagini produse',
'Shopify_G_Img_1' => 'Imaginile pleacă odată cu produsul la o {push} — mai întâi imaginea principală, apoi galeria, apoi câte una pentru fiecare variantă care are propria imagine, până la cincizeci.',
'Shopify_G_Products_Push' => 'trimitere de produse',
'Shopify_G_Img_2' => 'Imaginea unei variante este încărcată cu produsul și apoi {assigned}, așa cum o modelează Shopify: o variantă indică spre una dintre imaginile produsului. O variantă care refolosește imaginea principală nu o încarcă de două ori.',
'Shopify_G_Assigned' => 'atribuită acelei variante',
'Shopify_G_Img_3' => 'O imagine stocată ca fișier este {uploaded} în Shopify, nu legată, deci funcționează chiar și atunci când această instalare nu este accesibilă de pe internet. O imagine adăugată ca link lipit este transmisă către Shopify ca acel URL, care trebuie să fie accesibil public.',
'Shopify_G_Uploaded' => 'încărcată',
'Shopify_G_Img_4' => 'Sunt retrimise doar când se modifică efectiv — o trimitere care schimbă doar un preț lasă imaginile magazinului neatinse, deoarece trimiterea lor înlocuiește întregul set.',
'Shopify_G_Img_5' => 'Eliminarea unei imagini în ERP {not} o șterge în Shopify. Ștergeți-o și acolo, altfel magazinul continuă să o afișeze.',
'Shopify_G_Commands' => 'Comenzi utile',
'Shopify_G_Command_Copied' => 'Comandă copiată',
'Shopify_G_Foot' => 'Fiecare sincronizare scrie în {logs}, iar Prezentarea generală a fiecărui magazin arată când a rulat ultima dată fiecare pas, când este următoarea scadență și ce îl blochează, dacă ceva îl blochează. Acolo trebuie să vă uitați mai întâi când o sincronizare nu a făcut ce vă așteptați.',
'Shopify_G_Covers' => 'Acoperă',
'Shopify_G_Covers_Rt' => 'Comenzi și editări făcute în Shopify; stocul care pleacă din ERP (o vânzare POS, un retur, o ajustare)',
'Shopify_G_Covers_Sch' => 'Totul, în ambele direcții — inclusiv trimiterile de catalog și tot ce a ratat calea rapidă',
'Shopify_G_Speed' => 'Viteză',
