'StoreAdm_PG_Intro_Desc' => 'Cheile Stripe sunt partajate global (administrarea și magazinul online folosesc aceeași integrare Stripe). Fiecare filă activează sau dezactivează metoda sa pentru finalizarea comenzii din magazinul online; Plăți offline conține metodele plătite în afara sistemului.',
